// 작업 타임라인 컴포넌트
import { useState, useMemo } from 'react';
import type { Project, ProjectTask, ProjectTodo } from '../../types/work';
import './WorkTimeline.css';

// 타임라인 아이템 타입
type TimelineItemType = 'RANGE' | 'ALLDAY' | 'POINT' | 'UNSCHEDULED';

// 아이템 타입 결정
function getItemType(item: { start_at: string | null; end_at: string | null; due_at: string | null; is_all_day: boolean }): TimelineItemType {
  if (item.start_at && item.end_at) return 'RANGE';
  if (item.is_all_day && (item.start_at || item.due_at)) return 'ALLDAY';
  if (item.due_at) return 'POINT';
  return 'UNSCHEDULED';
}

// 날짜에서 YYYY-MM-DD 추출
function toDateString(isoDate: string | null): string | undefined {
  if (!isoDate) return undefined;
  return isoDate.split('T')[0];
}

// ===== Projects 월 타임라인 =====
interface ProjectsMonthTimelineProps {
  projects: Project[];
  showCompleted: boolean;
  onProjectClick?: (project: Project) => void;
  onAddClick?: () => void;
}

export function ProjectsMonthTimeline({ 
  projects, 
  onProjectClick,
  onAddClick 
}: ProjectsMonthTimelineProps) {
  const [currentMonth, setCurrentMonth] = useState(() => {
    const now = new Date();
    return `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
  });

  // 월의 날짜들 생성
  const { days, startDay } = useMemo(() => {
    const [year, month] = currentMonth.split('-').map(Number);
    const firstDay = new Date(year, month - 1, 1);
    const lastDay = new Date(year, month, 0);
    const totalDays = lastDay.getDate();
    const dayOfWeek = firstDay.getDay(); // 0 = Sunday

    const daysList: Date[] = [];
    for (let i = 1; i <= totalDays; i++) {
      daysList.push(new Date(year, month - 1, i));
    }
    return { days: daysList, startDay: dayOfWeek };
  }, [currentMonth]);

  // 프로젝트를 타임라인 아이템으로 변환
  const timelineItems = useMemo(() => {
    return projects.map(p => ({
      id: p.id,
      type: getItemType(p),
      title: p.title,
      color: p.color,
      startDate: toDateString(p.start_at),
      endDate: toDateString(p.end_at),
      dueDate: toDateString(p.due_at),
      isDone: p.status === 'ARCHIVED',
      originalItem: p,
    }));
  }, [projects]);

  // 특정 날짜에 해당하는 프로젝트 필터링
  const getProjectsForDate = (dateStr: string) => {
    return timelineItems.filter(item => {
      if (item.type === 'UNSCHEDULED') return false;
      
      if (item.startDate && item.endDate) {
        // RANGE: 시작일 <= 날짜 <= 종료일
        return dateStr >= item.startDate && dateStr <= item.endDate;
      }
      
      if (item.dueDate) {
        // POINT: 마감일 == 날짜
        return dateStr === item.dueDate;
      }
      
      if (item.startDate) {
        // ALLDAY: 시작일 == 날짜
        return dateStr === item.startDate;
      }
      
      return false;
    });
  };

  // 미정 프로젝트
  const unscheduledProjects = timelineItems.filter(item => item.type === 'UNSCHEDULED');

  const handlePrevMonth = () => {
    const [year, month] = currentMonth.split('-').map(Number);
    const prevDate = new Date(year, month - 2, 1);
    setCurrentMonth(`${prevDate.getFullYear()}-${String(prevDate.getMonth() + 1).padStart(2, '0')}`);
  };

  const handleNextMonth = () => {
    const [year, month] = currentMonth.split('-').map(Number);
    const nextDate = new Date(year, month, 1);
    setCurrentMonth(`${nextDate.getFullYear()}-${String(nextDate.getMonth() + 1).padStart(2, '0')}`);
  };

  const handleToday = () => {
    const now = new Date();
    setCurrentMonth(`${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`);
  };

  const formatMonth = (monthStr: string) => {
    const [year, month] = monthStr.split('-').map(Number);
    return `${year}년 ${month}월`;
  };

  return (
    <div className="work-timeline projects-timeline">
      {/* 툴바 */}
      <div className="timeline-toolbar">
        <div className="toolbar-left">
          <button className="nav-btn" onClick={handlePrevMonth}>‹</button>
          <button className="today-btn" onClick={handleToday}>오늘</button>
          <button className="nav-btn" onClick={handleNextMonth}>›</button>
          <span className="current-month">{formatMonth(currentMonth)}</span>
        </div>
        {onAddClick && (
          <button className="add-btn" onClick={onAddClick}>+ 프로젝트</button>
        )}
      </div>

      {/* 월 그리드 */}
      <div className="month-grid">
        {/* 요일 헤더 */}
        <div className="weekday-header">
          {['일', '월', '화', '수', '목', '금', '토'].map(day => (
            <div key={day} className="weekday">{day}</div>
          ))}
        </div>

        {/* 날짜 그리드 */}
        <div className="days-grid">
          {/* 빈 셀 (월 시작 전) */}
          {Array.from({ length: startDay }).map((_, i) => (
            <div key={`empty-${i}`} className="day-cell empty" />
          ))}

          {/* 날짜 셀 */}
          {days.map(date => {
            const dateStr = date.toISOString().split('T')[0];
            const dayProjects = getProjectsForDate(dateStr);
            const isToday = dateStr === new Date().toISOString().split('T')[0];
            const maxShow = 3;
            const moreCount = dayProjects.length - maxShow;

            return (
              <div key={dateStr} className={`day-cell ${isToday ? 'today' : ''}`}>
                <span className="day-number">{date.getDate()}</span>
                <div className="day-items">
                  {dayProjects.slice(0, maxShow).map(item => (
                    <div 
                      key={item.id}
                      className={`day-item ${item.type.toLowerCase()} ${item.isDone ? 'done' : ''}`}
                      style={{ backgroundColor: item.color }}
                      onClick={() => onProjectClick?.(item.originalItem as Project)}
                      title={item.title}
                    >
                      <span className="item-title">{item.title}</span>
                    </div>
                  ))}
                  {moreCount > 0 && (
                    <div className="more-items">+{moreCount}</div>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {/* 미정 영역 */}
      {unscheduledProjects.length > 0 && (
        <div className="unscheduled-section">
          <h4 className="section-title">📌 미정 ({unscheduledProjects.length})</h4>
          <div className="unscheduled-items">
            {unscheduledProjects.map(item => (
              <div 
                key={item.id}
                className={`unscheduled-item ${item.isDone ? 'done' : ''}`}
                onClick={() => onProjectClick?.(item.originalItem as Project)}
              >
                <span className="color-dot" style={{ backgroundColor: item.color }} />
                <span className="item-title">{item.title}</span>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

// ===== Tasks Day Agenda 타임라인 =====
interface TasksDayTimelineProps {
  tasks: ProjectTask[];
  doneTasks: ProjectTask[];
  projects: Project[];
  showCompleted: boolean;
  onTaskClick?: (task: ProjectTask) => void;
  onAddClick?: () => void;
}

export function TasksDayTimeline({ 
  tasks, 
  doneTasks,
  projects, 
  showCompleted,
  onTaskClick,
  onAddClick 
}: TasksDayTimelineProps) {
  const [currentDate, setCurrentDate] = useState(() => new Date().toISOString().split('T')[0]);

  // 프로젝트 색상 가져오기
  const getProjectColor = (projectId: string | null): string => {
    if (!projectId) return '#64748b';
    const project = projects.find(p => p.id === projectId);
    return project?.color || '#64748b';
  };

  const getProjectName = (projectId: string | null): string => {
    if (!projectId) return '미분류';
    const project = projects.find(p => p.id === projectId);
    return project?.title || '미분류';
  };

  // 태스크를 타임라인 아이템으로 변환
  const allTasks = showCompleted ? [...tasks, ...doneTasks] : tasks;

  // 날짜별 분류
  const { allDayTasks, timedTasks, unscheduledTasks } = useMemo(() => {
    const allDay: ProjectTask[] = [];
    const timed: ProjectTask[] = [];
    const unscheduled: ProjectTask[] = [];

    allTasks.forEach(task => {
      const type = getItemType(task);
      if (type === 'UNSCHEDULED') {
        unscheduled.push(task);
      } else if (type === 'ALLDAY') {
        const taskDate = toDateString(task.start_at || task.due_at);
        if (taskDate === currentDate) {
          allDay.push(task);
        }
      } else {
        // RANGE 또는 POINT
        const startDate = toDateString(task.start_at);
        const endDate = toDateString(task.end_at);
        const dueDate = toDateString(task.due_at);

        // 현재 날짜에 해당하는지 체크
        if (startDate && endDate) {
          if (currentDate >= startDate && currentDate <= endDate) {
            timed.push(task);
          }
        } else if (dueDate === currentDate || startDate === currentDate) {
          timed.push(task);
        }
      }
    });

    // 시간순 정렬
    timed.sort((a, b) => {
      const aTime = a.start_at || a.due_at || '';
      const bTime = b.start_at || b.due_at || '';
      return aTime.localeCompare(bTime);
    });

    return { allDayTasks: allDay, timedTasks: timed, unscheduledTasks: unscheduled };
  }, [allTasks, currentDate]);

  const handlePrevDay = () => {
    const date = new Date(currentDate);
    date.setDate(date.getDate() - 1);
    setCurrentDate(date.toISOString().split('T')[0]);
  };

  const handleNextDay = () => {
    const date = new Date(currentDate);
    date.setDate(date.getDate() + 1);
    setCurrentDate(date.toISOString().split('T')[0]);
  };

  const handleToday = () => {
    setCurrentDate(new Date().toISOString().split('T')[0]);
  };

  const formatDate = (dateStr: string) => {
    const date = new Date(dateStr);
    const days = ['일', '월', '화', '수', '목', '금', '토'];
    return `${date.getMonth() + 1}/${date.getDate()} (${days[date.getDay()]})`;
  };

  const formatTime = (isoDate: string | null): string => {
    if (!isoDate) return '';
    const date = new Date(isoDate);
    return `${String(date.getHours()).padStart(2, '0')}:${String(date.getMinutes()).padStart(2, '0')}`;
  };

  return (
    <div className="work-timeline tasks-timeline">
      {/* 툴바 */}
      <div className="timeline-toolbar">
        <div className="toolbar-left">
          <button className="nav-btn" onClick={handlePrevDay}>‹</button>
          <button className="today-btn" onClick={handleToday}>오늘</button>
          <button className="nav-btn" onClick={handleNextDay}>›</button>
          <span className="current-date">{formatDate(currentDate)}</span>
        </div>
        {onAddClick && (
          <button className="add-btn" onClick={onAddClick}>+ 태스크</button>
        )}
      </div>

      {/* All-day 영역 */}
      {allDayTasks.length > 0 && (
        <div className="allday-section">
          <h4 className="section-label">종일</h4>
          <div className="allday-items">
            {allDayTasks.map(task => (
              <div 
                key={task.id}
                className={`agenda-item allday ${task.status === 'DONE' ? 'done' : ''}`}
                onClick={() => onTaskClick?.(task)}
              >
                <span className="color-strip" style={{ backgroundColor: getProjectColor(task.projectId) }} />
                <div className="item-content">
                  <span className="item-title">{task.title}</span>
                  <span className="item-meta">{getProjectName(task.projectId)}</span>
                </div>
                {task.status === 'DONE' && <span className="done-check">✓</span>}
              </div>
            ))}
          </div>
        </div>
      )}

      {/* 시간대별 Agenda */}
      <div className="agenda-section">
        {timedTasks.length === 0 && allDayTasks.length === 0 ? (
          <div className="empty-agenda">
            <p>이 날짜에 예정된 태스크가 없습니다</p>
          </div>
        ) : (
          <div className="agenda-items">
            {timedTasks.map(task => (
              <div 
                key={task.id}
                className={`agenda-item ${task.status === 'DONE' ? 'done' : ''}`}
                onClick={() => onTaskClick?.(task)}
              >
                <span className="color-strip" style={{ backgroundColor: getProjectColor(task.projectId) }} />
                <div className="time-label">
                  {formatTime(task.start_at || task.due_at)}
                  {task.end_at && ` - ${formatTime(task.end_at)}`}
                </div>
                <div className="item-content">
                  <span className="item-title">{task.title}</span>
                  <span className="item-meta">{getProjectName(task.projectId)}</span>
                </div>
                {task.status === 'DONE' && <span className="done-check">✓</span>}
              </div>
            ))}
          </div>
        )}
      </div>

      {/* 미정 영역 */}
      {unscheduledTasks.length > 0 && (
        <div className="unscheduled-section">
          <h4 className="section-title">📌 미정 ({unscheduledTasks.length})</h4>
          <div className="unscheduled-items">
            {unscheduledTasks.map(task => (
              <div 
                key={task.id}
                className={`unscheduled-item ${task.status === 'DONE' ? 'done' : ''}`}
                onClick={() => onTaskClick?.(task)}
              >
                <span className="color-dot" style={{ backgroundColor: getProjectColor(task.projectId) }} />
                <span className="item-title">{task.title}</span>
                <span className="item-meta">{getProjectName(task.projectId)}</span>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

// ===== Todos Day Agenda 타임라인 =====
interface TodosDayTimelineProps {
  todos: ProjectTodo[];
  doneTodos: ProjectTodo[];
  tasks: ProjectTask[];
  projects: Project[];
  showCompleted: boolean;
  onTodoClick?: (todo: ProjectTodo) => void;
  onAddClick?: () => void;
}

export function TodosDayTimeline({ 
  todos, 
  doneTodos,
  tasks,
  projects, 
  showCompleted,
  onTodoClick,
  onAddClick 
}: TodosDayTimelineProps) {
  const [currentDate, setCurrentDate] = useState(() => new Date().toISOString().split('T')[0]);

  // 프로젝트/태스크 정보 가져오기
  const getTaskInfo = (taskId: string | null) => {
    if (!taskId) return { taskName: '미분류', projectName: '', color: '#64748b' };
    const task = tasks.find(t => t.id === taskId);
    if (!task) return { taskName: '미분류', projectName: '', color: '#64748b' };
    
    const project = task.projectId ? projects.find(p => p.id === task.projectId) : null;
    return {
      taskName: task.title,
      projectName: project?.title || '',
      color: project?.color || '#64748b',
    };
  };

  // 투두를 분류
  const allTodos = showCompleted ? [...todos, ...doneTodos] : todos;

  const { allDayTodos, timedTodos, unscheduledTodos } = useMemo(() => {
    const allDay: ProjectTodo[] = [];
    const timed: ProjectTodo[] = [];
    const unscheduled: ProjectTodo[] = [];

    allTodos.forEach(todo => {
      const type = getItemType(todo);
      if (type === 'UNSCHEDULED') {
        unscheduled.push(todo);
      } else if (type === 'ALLDAY') {
        const todoDate = toDateString(todo.start_at || todo.due_at);
        if (todoDate === currentDate) {
          allDay.push(todo);
        }
      } else {
        const startDate = toDateString(todo.start_at);
        const endDate = toDateString(todo.end_at);
        const dueDate = toDateString(todo.due_at);

        if (startDate && endDate) {
          if (currentDate >= startDate && currentDate <= endDate) {
            timed.push(todo);
          }
        } else if (dueDate === currentDate || startDate === currentDate) {
          timed.push(todo);
        }
      }
    });

    timed.sort((a, b) => {
      const aTime = a.start_at || a.due_at || '';
      const bTime = b.start_at || b.due_at || '';
      return aTime.localeCompare(bTime);
    });

    return { allDayTodos: allDay, timedTodos: timed, unscheduledTodos: unscheduled };
  }, [allTodos, currentDate]);

  const handlePrevDay = () => {
    const date = new Date(currentDate);
    date.setDate(date.getDate() - 1);
    setCurrentDate(date.toISOString().split('T')[0]);
  };

  const handleNextDay = () => {
    const date = new Date(currentDate);
    date.setDate(date.getDate() + 1);
    setCurrentDate(date.toISOString().split('T')[0]);
  };

  const handleToday = () => {
    setCurrentDate(new Date().toISOString().split('T')[0]);
  };

  const formatDate = (dateStr: string) => {
    const date = new Date(dateStr);
    const days = ['일', '월', '화', '수', '목', '금', '토'];
    return `${date.getMonth() + 1}/${date.getDate()} (${days[date.getDay()]})`;
  };

  const formatTime = (isoDate: string | null): string => {
    if (!isoDate) return '';
    const date = new Date(isoDate);
    return `${String(date.getHours()).padStart(2, '0')}:${String(date.getMinutes()).padStart(2, '0')}`;
  };

  return (
    <div className="work-timeline todos-timeline">
      {/* 툴바 */}
      <div className="timeline-toolbar">
        <div className="toolbar-left">
          <button className="nav-btn" onClick={handlePrevDay}>‹</button>
          <button className="today-btn" onClick={handleToday}>오늘</button>
          <button className="nav-btn" onClick={handleNextDay}>›</button>
          <span className="current-date">{formatDate(currentDate)}</span>
        </div>
        {onAddClick && (
          <button className="add-btn" onClick={onAddClick}>+ 투두</button>
        )}
      </div>

      {/* All-day 영역 */}
      {allDayTodos.length > 0 && (
        <div className="allday-section">
          <h4 className="section-label">종일</h4>
          <div className="allday-items">
            {allDayTodos.map(todo => {
              const info = getTaskInfo(todo.taskId);
              return (
                <div 
                  key={todo.id}
                  className={`agenda-item allday ${todo.is_done ? 'done' : ''}`}
                  onClick={() => onTodoClick?.(todo)}
                >
                  <span className="color-strip" style={{ backgroundColor: info.color }} />
                  <div className="item-content">
                    <span className="item-title">{todo.content}</span>
                    <span className="item-meta">
                      {info.projectName && `${info.projectName} / `}{info.taskName}
                    </span>
                  </div>
                  {todo.is_done && <span className="done-check">✓</span>}
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* 시간대별 Agenda */}
      <div className="agenda-section">
        {timedTodos.length === 0 && allDayTodos.length === 0 ? (
          <div className="empty-agenda">
            <p>이 날짜에 예정된 투두가 없습니다</p>
          </div>
        ) : (
          <div className="agenda-items">
            {timedTodos.map(todo => {
              const info = getTaskInfo(todo.taskId);
              return (
                <div 
                  key={todo.id}
                  className={`agenda-item ${todo.is_done ? 'done' : ''}`}
                  onClick={() => onTodoClick?.(todo)}
                >
                  <span className="color-strip" style={{ backgroundColor: info.color }} />
                  <div className="time-label">
                    {formatTime(todo.start_at || todo.due_at)}
                    {todo.end_at && ` - ${formatTime(todo.end_at)}`}
                  </div>
                  <div className="item-content">
                    <span className="item-title">{todo.content}</span>
                    <span className="item-meta">
                      {info.projectName && `${info.projectName} / `}{info.taskName}
                    </span>
                  </div>
                  {todo.is_done && <span className="done-check">✓</span>}
                </div>
              );
            })}
          </div>
        )}
      </div>

      {/* 미정 영역 */}
      {unscheduledTodos.length > 0 && (
        <div className="unscheduled-section">
          <h4 className="section-title">📌 미정 ({unscheduledTodos.length})</h4>
          <div className="unscheduled-items">
            {unscheduledTodos.map(todo => {
              const info = getTaskInfo(todo.taskId);
              return (
                <div 
                  key={todo.id}
                  className={`unscheduled-item ${todo.is_done ? 'done' : ''}`}
                  onClick={() => onTodoClick?.(todo)}
                >
                  <span className="color-dot" style={{ backgroundColor: info.color }} />
                  <span className="item-title">{todo.content}</span>
                  <span className="item-meta">
                    {info.projectName && `${info.projectName} / `}{info.taskName}
                  </span>
                </div>
              );
            })}
          </div>
        </div>
      )}
    </div>
  );
}
